for i,(prompt,opts,ans,ex,strategy) in enumerate(DATA,1):
 p=D/f'question-science-content-cross-disciplinary-{i}.json'; old=json.loads(p.read_text()); text=opts[ord(ans)-65]
 old.update({'prompt':prompt,'options':[{'id':chr(65+j),'text':x} for j,x in enumerate(opts)],'answer':{'value':ans,'explanation':ex+f' 正確答案為選項 {ans}：「{text}」。'},'solutionStrategy':strategy,'solutionSteps':['定位概念：圈出跨科探究題的研究問題、變因、資料或模型。','整理證據：分開操縱變因、依變因、控制條件、樣本與誤差。',f'套用原理：{ex}',f'排除干擾：檢查方法可重複性、對照與推論範圍，正確選項是「{text}」。',f'最後回查：答案「{text}」符合題幹，沒有把有限資料誇大成普遍定律。'],'reviewStatus':'draft','updatedAt':'2026-09-08'})
 p.write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n')
print(f'rewrote {len(DATA)} questions')
